import { useMemo, useState } from 'react'
import { Icon, type IconName } from '@/design-system/Icon'
import { Card, EmptyState, Field, PARTNER_VISIBILITY_OPTIONS, Sheet, VisibilityBadge } from '@/components/ui'
import { useSession } from '@/app/session'
import { useOwned } from '@/db/hooks'
import { db, newEnvelope, softDelete } from '@/db/db'
import type { CalendarEvent, Memory, Visibility } from '@/types/domain'
import { useI18n, type MessageKey } from '@/i18n'
import { whenLabel } from '@/i18n/format'
import {
  BUDGETS,
  DURATIONS,
  ENERGIES,
  IDEAS,
  MOODS,
  PLACES,
  filterIdeas,
  pickOne,
  type Filters,
  type Idea,
  type Mood,
} from './ideas'
import { hasMemoryFor, splitPlans, toLocalISODate } from './plan'

/**
 * Ide kencan — a catalogue plus a filter, and one door out of it: a chosen idea
 * becomes a calendar event, and once the day has passed, a memory.
 *
 * The catalogue is deliberately generic. Naming a real café or a real park would
 * be inventing a fact with real-world consequences (it closed, it moved, it was
 * never there), so the ideas describe a *kind* of outing and leave the choosing
 * to the people who live in that city.
 */

/** Every axis gets an icon from the existing set — no new glyphs, no emoji. */
const AXIS_ICON = {
  budget: 'money',
  duration: 'calendar',
  place: 'home',
  energy: 'checkin',
  mood: 'date',
} as const satisfies Record<keyof Filters, IconName>

const MOOD_ICON: Record<Mood, IconName> = {
  santai: 'home',
  romantis: 'heart',
  aktif: 'health',
  kreatif: 'memories',
  kuliner: 'groceries',
  tenang: 'self',
}

export default function DateIdeas() {
  const { t, locale } = useI18n()
  const { profile } = useSession()
  const me = profile?.id
  const [filters, setFilters] = useState<Filters>({})
  const [planning, setPlanning] = useState<Idea | null>(null)

  const events = useOwned<CalendarEvent>('events', me)
  const memories = useOwned<Memory>('memories', me)
  const today = toLocalISODate(new Date())
  const { upcoming, past } = splitPlans(events ?? [], today)

  // Only recomputed when a filter changes; the catalogue itself never does.
  const matches = useMemo(() => filterIdeas(IDEAS, filters), [filters])

  if (!profile || !me) return null

  const set = <K extends keyof Filters>(key: K, value: string) =>
    setFilters((f) => ({ ...f, [key]: value === '' ? undefined : (value as Filters[K]) }))

  const active = Object.values(filters).some(Boolean)

  async function saveMemory(plan: CalendarEvent) {
    if (!me) return
    await db.memories.add({
      ...newEnvelope(me, 'C2_shared_ops', { visibility: plan.visibility }),
      kind: 'memory',
      title: plan.title,
      date: plan.date,
      ...(plan.note ? { story: plan.note } : {}),
      isMilestone: false,
    } as never)
  }

  return (
    <div className="stack">
      <h1>{t('dates.title')}</h1>
      <p className="card__hint">{t('dates.subtitle')}</p>

      <Card title={t('dates.plans')} icon="date" hint={t('dates.plansHint')}>
        {upcoming.length === 0 && past.length === 0 ? (
          <EmptyState icon="date" title={t('dates.noPlans')} hint={t('dates.noPlansHint')} />
        ) : (
          <div className="stack stack--tight">
            {upcoming.length > 0 && <h3 className="card__hint">{t('dates.upcoming')}</h3>}
            <ul className="list" hidden={upcoming.length === 0}>
              {upcoming.map((p) => (
                <li key={p.id} className="list__item">
                  <Icon name="date" size={18} />
                  <span className="grow stack stack--tight">
                    <strong style={{ fontSize: 14 }}>{p.title}</strong>
                    <span className="card__hint">
                      {whenLabel(p.date, t, locale)}
                      {p.time ? ` · ${p.time}` : ''}
                    </span>
                  </span>
                  <VisibilityBadge visibility={p.visibility} />
                  <button
                    className="btn btn--ghost btn--sm btn--icon"
                    onClick={() => softDelete('events', p.id, me)}
                  >
                    <Icon name="close" size={16} label={t('common.deleteX', { name: p.title })} />
                  </button>
                </li>
              ))}
            </ul>

            {past.length > 0 && <h3 className="card__hint">{t('dates.past')}</h3>}
            <ul className="list" hidden={past.length === 0}>
              {past.map((p) => {
                const kept = hasMemoryFor(p, memories ?? [])
                return (
                  <li key={p.id} className="list__item">
                    <Icon name={kept ? 'memories' : 'date'} size={18} />
                    <span className="grow stack stack--tight">
                      <strong style={{ fontSize: 14 }}>{p.title}</strong>
                      <span className="card__hint">{whenLabel(p.date, t, locale)}</span>
                    </span>
                    {kept ? (
                      <span className="chip chip--mint">
                        <Icon name="check" size={14} />
                        {t('dates.isMemory')}
                      </span>
                    ) : (
                      <button className="btn btn--soft btn--sm" onClick={() => saveMemory(p)}>
                        <Icon name="memories" size={16} /> {t('dates.toMemory')}
                      </button>
                    )}
                  </li>
                )
              })}
            </ul>
          </div>
        )}
      </Card>

      <Card title={t('dates.filters')} icon="date">
        <div className="stack stack--tight">
          <Axis axis="budget" values={BUDGETS} value={filters.budget} onPick={set} hint />
          <Axis axis="duration" values={DURATIONS} value={filters.duration} onPick={set} hint />
          <Axis axis="place" values={PLACES} value={filters.place} onPick={set} />
          <Axis axis="energy" values={ENERGIES} value={filters.energy} onPick={set} hint />
          <Axis axis="mood" values={MOODS} value={filters.mood} onPick={set} />
        </div>
        <div className="row row--between" style={{ marginTop: 'var(--space-3)' }}>
          <span className="card__hint">{t('dates.count', { n: matches.length })}</span>
          <span className="row">
            {active && (
              <button className="btn btn--ghost btn--sm" onClick={() => setFilters({})}>
                {t('dates.reset')}
              </button>
            )}
            <button
              className="btn btn--sm"
              disabled={matches.length === 0}
              onClick={() => setPlanning(pickOne(matches, Math.random()) ?? null)}
            >
              <Icon name="date" size={16} /> {t('dates.surprise')}
            </button>
          </span>
        </div>
      </Card>

      {matches.length === 0 ? (
        <Card>
          <EmptyState icon="info" title={t('dates.none')} hint={t('dates.noneHint')} />
        </Card>
      ) : (
        <ul className="list">
          {matches.map((idea) => (
            <li key={idea.id} className="list__item">
              {/* The mood is only carried by this icon, so it gets a label. */}
              <Icon
                name={MOOD_ICON[idea.moods[0]!]}
                size={18}
                label={t(`dates.mood.${idea.moods[0]!}` as MessageKey)}
              />
              <span className="grow stack stack--tight">
                <strong style={{ fontSize: 14 }}>{t(`dates.idea.${idea.id}` as MessageKey)}</strong>
                <span className="row" style={{ gap: 6 }}>
                  <span className="chip">{t(`dates.budget.${idea.budget}` as MessageKey)}</span>
                  <span className="chip">{t(`dates.duration.${idea.duration}` as MessageKey)}</span>
                  <span className="chip">{t(`dates.place.${idea.place}` as MessageKey)}</span>
                  <span className="chip">{t(`dates.energy.${idea.energy}` as MessageKey)}</span>
                </span>
              </span>
              <button className="btn btn--sm" onClick={() => setPlanning(idea)}>
                <Icon name="plus" size={16} /> {t('dates.plan')}
              </button>
            </li>
          ))}
        </ul>
      )}

      <p className="disclaimer">{t('dates.disclaimer')}</p>

      <PlanSheet idea={planning} me={me} onClose={() => setPlanning(null)} />
    </div>
  )
}

/** One filter axis: a native select, so six options still fit at 320 px. */
function Axis<K extends keyof Filters>({
  axis,
  values,
  value,
  onPick,
  hint,
}: {
  axis: K
  values: readonly string[]
  value: string | undefined
  onPick: (key: K, value: string) => void
  hint?: boolean
}) {
  const { t } = useI18n()
  const id = `dates-filter-${String(axis)}`
  return (
    <div className="field">
      <label htmlFor={id} className="row" style={{ gap: 6 }}>
        <Icon name={AXIS_ICON[axis]} size={16} />
        {t(`dates.axis.${String(axis)}` as MessageKey)}
      </label>
      <select id={id} value={value ?? ''} onChange={(e) => onPick(axis, e.target.value)}>
        <option value="">{t('dates.any')}</option>
        {values.map((v) => (
          // The option key namespace is the axis name: `dates.mood.santai`, etc.
          <option key={v} value={v}>
            {t(`dates.${String(axis)}.${v}` as MessageKey)}
          </option>
        ))}
      </select>
      {hint && <span className="field__hint">{t(`dates.axis.${String(axis)}Hint` as MessageKey)}</span>}
    </div>
  )
}

/**
 * Planning writes a `CalendarEvent` of type `date` — the same record the calendar
 * screen reads. There is no separate plan store to keep in step.
 */
function PlanSheet({ idea, me, onClose }: { idea: Idea | null; me: string; onClose: () => void }) {
  const { t } = useI18n()
  const [date, setDate] = useState(() => toLocalISODate(new Date()))
  const [time, setTime] = useState('')
  const [note, setNote] = useState('')
  const [visibility, setVis] = useState<Visibility>('shared')
  const title = idea ? t(`dates.idea.${idea.id}` as MessageKey) : ''

  // The note belongs to the outing, not to the sheet: clearing on close stops a
  // half-typed note following the next idea the user opens.
  function close() {
    setNote('')
    setTime('')
    onClose()
  }

  async function save() {
    if (!idea) return
    await db.events.add({
      ...newEnvelope(me, 'C2_shared_ops', { visibility }),
      kind: 'event',
      title,
      date,
      ...(time ? { time } : {}),
      type: 'date',
      ...(note.trim() ? { note: note.trim() } : {}),
    } as never)
    close()
  }

  return (
    <Sheet open={idea !== null} onClose={close} title={t('dates.planTitle', { idea: title })}>
      <div className="stack">
        <Field label={t('common.date')}>
          {(p) => <input {...p} type="date" value={date} onChange={(e) => setDate(e.target.value)} />}
        </Field>
        <Field label={t('common.time')} hint={t('common.optional')}>
          {(p) => <input {...p} type="time" value={time} onChange={(e) => setTime(e.target.value)} />}
        </Field>
        <Field label={t('dates.planNote')} hint={t('common.optional')}>
          {(p) => <textarea {...p} value={note} onChange={(e) => setNote(e.target.value)} />}
        </Field>
        <Field label={t('common.whoCanSee')}>
          {(p) => (
            <select {...p} value={visibility} onChange={(e) => setVis(e.target.value as Visibility)}>
              {PARTNER_VISIBILITY_OPTIONS.map((v) => (
                <option key={v} value={v}>
                  {t(`vis.opt.${v}` as const)}
                </option>
              ))}
            </select>
          )}
        </Field>
        <button className="btn btn--block" onClick={save}>
          {t('common.save')}
        </button>
      </div>
    </Sheet>
  )
}
