/**
 * Date-idea catalogue and the filter over it.
 *
 * The catalogue is static content, not user data: it never changes, nobody owns
 * it, and it carries nothing private — so it lives in code rather than in a
 * store. Only what the pair actually *plans* becomes a record (see plan.ts).
 *
 * No copy here, only keys: `dates.idea.<id>` resolves in messages.ts, which is
 * what keeps this module usable from a test and translatable at the same time.
 */

/** Ordered cheapest → priciest. Order is the whole point: the filter is a ceiling. */
export const BUDGETS = ['gratis', 'lt50', 'k50_150', 'k150_500', 'lebih'] as const
export const DURATIONS = ['m30', 'j1', 'j2', 'setengah', 'sehari'] as const
export const ENERGIES = ['capek', 'rendah', 'normal', 'aktif'] as const
/** Unordered: a place is a match or it is not. */
export const PLACES = ['rumah', 'dekat', 'indoor', 'outdoor', 'online'] as const
export const MOODS = ['santai', 'romantis', 'aktif', 'kreatif', 'kuliner', 'tenang'] as const

export type Budget = (typeof BUDGETS)[number]
export type Duration = (typeof DURATIONS)[number]
export type Energy = (typeof ENERGIES)[number]
export type Place = (typeof PLACES)[number]
export type Mood = (typeof MOODS)[number]

export interface Idea {
  id: string
  budget: Budget
  duration: Duration
  place: Place
  /** How much energy the idea *asks for*, not how much anyone has. */
  energy: Energy
  moods: Mood[]
}

export interface Filters {
  budget?: Budget
  duration?: Duration
  place?: Place
  energy?: Energy
  mood?: Mood
}

const rank = <T extends readonly string[]>(scale: T, v: T[number]) => scale.indexOf(v)

/**
 * Budget, duration and energy filter as ceilings ("segini ke bawah"), because
 * that is how people actually ask: someone with 50rb and an hour is happy to be
 * shown the free thirty-minute idea, and annoyed to have it hidden. Place and
 * mood are plain matches — there is no "less than outdoor".
 */
export function filterIdeas(ideas: readonly Idea[], f: Filters): Idea[] {
  return ideas.filter(
    (i) =>
      (!f.budget || rank(BUDGETS, i.budget) <= rank(BUDGETS, f.budget)) &&
      (!f.duration || rank(DURATIONS, i.duration) <= rank(DURATIONS, f.duration)) &&
      (!f.energy || rank(ENERGIES, i.energy) <= rank(ENERGIES, f.energy)) &&
      (!f.place || i.place === f.place) &&
      (!f.mood || i.moods.includes(f.mood)),
  )
}

/** `r` comes from the caller (Math.random) so the picker itself stays testable. */
export function pickOne<T>(list: readonly T[], r: number): T | undefined {
  if (list.length === 0) return undefined
  const i = Math.floor(Math.max(0, Math.min(0.999999, r)) * list.length)
  return list[i]
}

