import type { CalendarEvent, Memory } from '@/types/domain'

/**
 * A planned date is a calendar event of type `date` — not a second store.
 *
 * Which means a date planned here shows up in the calendar, and one planned in
 * the calendar shows up here, without any syncing code. `datePlans` as its own
 * store would have bought a duplicate list the two screens could disagree about.
 */

export function isDatePlan(e: CalendarEvent): boolean {
  return e.type === 'date'
}

/** Local calendar date. `toISOString()` is UTC and lands on yesterday before 07:00 WIB. */
export function toLocalISODate(d: Date): string {
  const pad = (n: number) => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

/** Upcoming ascending (soonest first), past descending (most recent first). */
export function splitPlans(
  events: readonly CalendarEvent[],
  today: string,
): { upcoming: CalendarEvent[]; past: CalendarEvent[] } {
  const plans = events.filter(isDatePlan)
  return {
    upcoming: plans.filter((e) => e.date >= today).sort((a, b) => a.date.localeCompare(b.date)),
    past: plans.filter((e) => e.date < today).sort((a, b) => b.date.localeCompare(a.date)),
  }
}

const occasionKey = (x: { title: string; date: string }) =>
  `${x.date}|${x.title.trim().toLowerCase()}`

/**
 * A plan becomes a memory by copying it, so there is no link field to migrate.
 * Same day + same title is the match: it is what a person would call "the same
 * date", and it keeps the button from silently making duplicates on a double tap.
 */
export function hasMemoryFor(plan: CalendarEvent, memories: readonly Memory[]): boolean {
  const key = occasionKey(plan)
  return memories.some((m) => occasionKey(m) === key)
}
